def apply(inputs, premises):
    timing_ok = inputs["payment_upon_or_after_termination"] == premises["required_timing"]
    cause_ok = inputs["termination_cause"] in premises["qualifying_termination_causes"]
    if timing_ok and cause_ok:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}

def apply(inputs, premises):
    total = int(inputs["ticket_price"])
    n = len(inputs["checked_item_numbers"])
    for i in range(n):
        base_fee = int(inputs["checked_base_fees"][i])
        overweight_fee = int(inputs["checked_overweight_fees"][i])
        oversize_fee = int(inputs["checked_oversize_fees"][i])
        if premises["excess_fee_combination"] == "higher_only":
            excess_fee = max(overweight_fee, oversize_fee)
        else:
            excess_fee = overweight_fee + oversize_fee
        if premises["checked_fee_is_additive"]:
            total = total + base_fee + excess_fee
        else:
            total = total + max(base_fee, excess_fee)
    return {"answer": total}
